open(p,'w').write(s)
E
mkdir -p src/v4/core/tests; cat > src/v4/core/tests/treeshake.test.ts <<'E'
import { build } from "esbuild";
import { expect, test } from "vitest";

async function bundle(entry: string) {
  const result = await build({
    stdin: {
      contents: `import * as z from ${JSON.stringify(entry)};\nconsole.log(z.boolean().parse(true));`,
      resolveDir: __dirname,
      loader: "ts",
    },
    bundle: true,
    minify: true,
    format: "esm",
    target: "es2020",
    treeShaking: true,
    write: false,
  });
  return result.outputFiles[0].text;
}

test("zod/mini tree-shakes unused declarations", async () => {
  const out = await bundle("../../mini/index.js");
  expect(out).toContain("boolean");
  for (const s of ["zod_brand", "MAX_SAFE_INTEGER", "02-29"]) expect(out).not.toContain(s);
});

test("zod classic tree-shakes registry symbols", async () => {
  const out = await bundle("../../classic/index.js");
  expect(out).toContain("boolean");
  for (const s of ["ZodOutput", "ZodInput"]) expect(out).not.toContain(s);
});
E
